toolResponse.stdout:
.command('promote <ref>')
.description('Promote observation to a task')
.requiredOption('--title <title>', 'Task title')
.option('--priority <priority>', 'Task priority', '2')
.option('--force', 'Force promotion even if observation is resolved')
.action(async (ref: string, options) => {
  try {
    const ctx = await initContext();

    if (!ctx.manifestPath) {
      error('No kspec manifest found');
      console.log('Run `kspec init` to create a new project');
      process.exit(1);
    }

    const manifest = await loadMetaManifest(ctx);

    if (!manifest) {
      error('No meta manifest found (kynetic.meta.yaml)');
      console.log('The meta manifest defines agents, workflows, and conventions for the project.');
      process.exit(1);
    }

    // Find observation
    const observation = manifest.observations.find((obs) => obs._ulid.startsWith(ref.replace('@', '')));

    if (!observation) {
      error(`Observation not found: ${ref}`);
      process.exit(1);
    }

    // Check if already promoted
    if (observation.promoted_to) {
      error(`Observation already promoted to task ${observation.promoted_to}; resolve or delete the task first`);
      process.exit(1);
    }

    // Check if resolved
    if (observation.resolved && !options.force) {
      error(`Cannot promote resolved observation; use --force to override`);
      process.exit(1);
    }

    // Create task
    const { spawn } = await import('child_process');
    const { promisify } = await import('util');
    const execFile = promisify(spawn);

    // Build task add command
    const taskArgs = [
      'run',
      'dev',
      '--',
      'task',
      'add',
      '--title',
      options.title,
      '--priority',
      options.priority,
    ];

    if (observation.workflow_ref) {
      taskArgs.push('--meta-ref', observation.workflow_ref);
    }

    // Add tags
    for (const tag of observation.tags) {
      taskArgs.push('--tag', tag);
    }

    // Execute task add command
    const result = await new Promise<{ taskRef: string }>((resolve, reject) => {
      const proc = spawn('npm', taskArgs, {
        cwd: ctx.rootDir,
        stdio: ['inherit', 'pipe', 'inherit'],
      });

      let output = '';
      proc.stdout?.on('data', (data) => {
        output += data.toString();
      });

