// Execute task add command and capture output
const taskRef = await new Promise<string>((resolve, reject) => {
  const proc = spawn('npm', taskArgs, {
    cwd: ctx.rootDir,
    stdio: ['inherit', 'pipe', 'inherit'],
  });

  let output = '';
  proc.stdout?.on('data', (data) => {
    output += data.toString();
  });

  proc.on('close', (code) => {
    if (code !== 0) {
      reject(new Error('Failed to create task'));
      return;
    }

    // Extract task ref from output (format: "OK Created task: <ULID>")
    const match = output.match(/Created task: (@?[A-Z0-9]+)/i);
    if (!match) {
      reject(new Error('Could not parse task ref from output'));
      return;
    }

    resolve(match[1].startsWith('@') ? match[1] : `@${match[1]}`);
  });
});

