import { z } from 'zod';
import {
  UlidSchema,
  SlugSchema,
  RefSchema,
  DateTimeSchema,
  TaskStatusSchema,
  TaskTypeSchema,
  VcsRefSchema,
} from './common.js';

/**
 * Note entry - append-only work log
 */
export const NoteSchema = z.object({
  _ulid: UlidSchema,
  created_at: DateTimeSchema,
  author: z.string().optional(),
  content: z.string(),
  supersedes: UlidSchema.nullable().optional(),
});

/**
 * Todo item - lightweight checklist
 */
export const TodoSchema = z.object({
  id: z.number().int().positive(),
  text: z.string(),
  done: z.boolean().default(false),
  done_at: DateTimeSchema.optional(),
  added_at: DateTimeSchema,
  added_by: z.string().optional(),
  promoted_to: RefSchema.optional(),
});

/**
 * Full task schema
 * Note: created_at defaults to now if not provided (auto-populated on load)
 */
export const TaskSchema = z.object({
  // Identity
  _ulid: UlidSchema,
  slugs: z.array(SlugSchema).default([]),
  title: z.string().min(1, 'Title is required'),
  type: TaskTypeSchema.default('task'),

  // Content (doesn't duplicate spec - brief description for standalone context)
  description: z.string().optional(),

  // Spec relationship
  spec_ref: RefSchema.nullable().optional(),
  derivation: z.enum(['auto', 'manual']).optional(),

  // State
  status: TaskStatusSchema.default('pending'),
  blocked_by: z.array(z.string()).default([]),
  closed_reason: z.string().nullable().optional(),

  // Dependencies
  depends_on: z.array(RefSchema).default([]),
  context: z.array(RefSchema).default([]),

  // Work metadata
  priority: z.number().int().min(1).max(5).default(3),
  complexity: z.number().int().min(1).max(5).optional(),
  tags: z.array(z.string()).default([]),
  assignee: z.string().nullable().optional(),

  // VCS references
  vcs_refs: z.array(VcsRefSchema).default([]),

  // Timestamps (auto-populated if not provided)
  created_at: DateTimeSchema.default(() => new Date().toISOString()),
  started_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  notes: z.array(NoteSchema).default([]),

  // Todos (emergent subtasks)
  todos: z.array(TodoSchema).default([]),
});

/**
 * Task input schema (for creating new tasks, some fields auto-generated)
 * All fields except title are optional - defaults will be applied
 */
export const TaskInputSchema = z.object({
  // Identity (auto-generated if not provided)
  _ulid: UlidSchema.optional(),
  slugs: z.array(SlugSchema).optional(),
  title: z.string().min(1, 'Title is required'),
  type: TaskTypeSchema.optional(),

  // Content
  description: z.string().optional(),

  // Spec relationship
  spec_ref: RefSchema.nullable().optional(),
  derivation: z.enum(['auto', 'manual']).optional(),

  // State
  status: TaskStatusSchema.optional(),
  blocked_by: z.array(z.string()).optional(),
  closed_reason: z.string().nullable().optional(),

  // Dependencies
  depends_on: z.array(RefSchema).optional(),
  context: z.array(RefSchema).optional(),

  // Work metadata
  priority: z.number().int().min(1).max(5).optional(),
  complexity: z.number().int().min(1).max(5).optional(),
  tags: z.array(z.string()).optional(),
  assignee: z.string().nullable().optional(),

  // VCS references
  vcs_refs: z.array(VcsRefSchema).optional(),

  // Timestamps
  created_at: DateTimeSchema.optional(),
  started_at: DateTimeSchema.nullable().optional(),
  completed_at: DateTimeSchema.nullable().optional(),

  // Notes (work log)
  notes: z.array(NoteSchema).optional(),

  // Todos (emergent subtasks)
  todos: z.array(TodoSchema).optional(),
});

/**
 * Tasks file schema (collection of tasks)
 */
export const TasksFileSchema = z.object({
  kynetic_tasks: z.string().default('1.0'),
  tasks: z.array(TaskSchema),
});

export type Note = z.infer<typeof NoteSchema>;
export type Todo = z.infer<typeof TodoSchema>;
export type Task = z.infer<typeof TaskSchema>;
export type TaskInput = z.infer<typeof TaskInputSchema>;
export type TasksFile = z.infer<typeof TasksFileSchema>;

import { Command } from 'commander';
import { ulid } from 'ulid';
import {
  initContext,
  loadAllTasks,
  loadAllItems,
  saveTask,
  deleteTask,
  createTask,
  createNote,
  createTodo,
  syncSpecImplementationStatus,
  ReferenceIndex,
  checkSlugUniqueness,
  type LoadedTask,
} from '../../parser/index.js';
import { commitIfShadow } from '../../parser/shadow.js';
import {
  output,
  formatTaskDetails,
  success,
  error,
  warn,
  info,
  isJsonMode,
} from '../output.js';
import { formatCommitGuidance, printCommitGuidance } from '../../utils/commit.js';
import type { Task, TaskInput } from '../../schema/index.js';

/**
 * Find a task by reference with detailed error reporting.
 * Returns the task or exits with appropriate error.
 */
function resolveTaskRef(
  ref: string,
  tasks: LoadedTask[],
  index: ReferenceIndex
): LoadedTask {
  const result = index.resolve(ref);

  if (!result.ok) {
    switch (result.error) {
      case 'not_found':
        error(`Task not found: ${ref}`);
        break;
      case 'ambiguous':
        error(`Reference "${ref}" is ambiguous. Matches:`);
        for (const candidate of result.candidates) {
          const task = tasks.find(t => t._ulid === candidate);
          const slug = task?.slugs[0] || '';
          console.error(`  - ${index.shortUlid(candidate)} ${slug ? `(${slug})` : ''}`);
        }
        break;
      case 'duplicate_slug':
        error(`Slug "${ref}" maps to multiple items. Use ULID instead:`);
        for (const candidate of result.candidates) {
          console.error(`  - ${index.shortUlid(candidate)}`);
        }
        break;
    }
    process.exit(3);
  }

  // Check if it's actually a task
  const task = tasks.find(t => t._ulid === result.ulid);
  if (!task) {
    error(`Reference "${ref}" is not a task (it's a spec item)`);
    process.exit(3);
  }

  return task;
}

/**
 * Register the 'task' command group (singular - operations on individual tasks)
 */
export function registerTaskCommands(program: Command): void {
  const task = program
    .command('task')
    .description('Operations on individual tasks');

  // kspec task get <ref>
  task
    .command('get <ref>')
    .description('Get task details')
    .action(async (ref: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        output(foundTask, () => formatTaskDetails(foundTask, index));
      } catch (err) {
        error('Failed to get task', err);
        process.exit(1);
      }
    });

  // kspec task add
  task
    .command('add')
    .description('Create a new task')
    .requiredOption('--title <title>', 'Task title')
    .option('--type <type>', 'Task type (task, epic, bug, spike, infra)', 'task')
    .option('--spec-ref <ref>', 'Reference to spec item')
    .option('--priority <n>', 'Priority (1-5)', '3')
    .option('--slug <slug>', 'Human-friendly slug')
    .option('--tag <tag...>', 'Tags')
    .action(async (options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);

        // Check slug uniqueness if provided
        if (options.slug) {
          const refIndex = new ReferenceIndex(tasks, items);
          const slugCheck = checkSlugUniqueness(refIndex, [options.slug]);
          if (!slugCheck.ok) {
            error(`Slug '${slugCheck.slug}' already exists (used by ${slugCheck.existingUlid})`);
            process.exit(1);
          }
        }

        const input: TaskInput = {
          title: options.title,
          type: options.type,
          spec_ref: options.specRef || null,
          priority: parseInt(options.priority, 10),
          slugs: options.slug ? [options.slug] : [],
          tags: options.tag || [],
        };

        const newTask = createTask(input);
        await saveTask(ctx, newTask);
        await commitIfShadow(ctx.shadow, 'task-add', newTask.slugs[0] || newTask._ulid.slice(0, 8), newTask.title);

        // Build index including the new task for accurate short ULID
        const index = new ReferenceIndex([...tasks, newTask], items);
        success(`Created task: ${index.shortUlid(newTask._ulid)}`, { task: newTask });
      } catch (err) {
        error('Failed to create task', err);
        process.exit(1);
      }
    });

  // kspec task set <ref>
  task
    .command('set <ref>')
    .description('Update task fields')
    .option('--title <title>', 'Update task title')
    .option('--spec-ref <ref>', 'Link to spec item')
    .option('--priority <n>', 'Set priority (1-5)')
    .option('--slug <slug>', 'Add a slug alias')
    .option('--tag <tag...>', 'Add tags')
    .option('--depends-on <refs...>', 'Set dependencies (replaces existing)')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        // Check slug uniqueness if adding a new slug
        if (options.slug) {
          const slugCheck = checkSlugUniqueness(index, [options.slug], foundTask._ulid);
          if (!slugCheck.ok) {
            error(`Slug '${slugCheck.slug}' already exists (used by ${slugCheck.existingUlid})`);
            process.exit(1);
          }
        }

        // Build updated task with only provided options
        const updatedTask: Task = { ...foundTask };
        const changes: string[] = [];

        if (options.title) {
          updatedTask.title = options.title;
          changes.push('title');
        }

        if (options.specRef) {
          // Validate the spec ref exists and is a spec item
          const specResult = index.resolve(options.specRef);
          if (!specResult.ok) {
            error(`Spec reference not found: ${options.specRef}`);
            process.exit(3);
          }
          // Check it's not a task
          const isTask = tasks.some(t => t._ulid === specResult.ulid);
          if (isTask) {
            error(`Reference "${options.specRef}" is a task, not a spec item`);
            process.exit(3);
          }
          updatedTask.spec_ref = options.specRef;
          changes.push('spec_ref');
        }

        if (options.priority) {
          const priority = parseInt(options.priority, 10);
          if (isNaN(priority) || priority < 1 || priority > 5) {
            error('Priority must be between 1 and 5');
            process.exit(3);
          }
          updatedTask.priority = priority;
          changes.push('priority');
        }

        if (options.slug) {
          if (!updatedTask.slugs.includes(options.slug)) {
            updatedTask.slugs = [...updatedTask.slugs, options.slug];
            changes.push('slug');
          }
        }

        if (options.tag) {
          const newTags = options.tag.filter((t: string) => !updatedTask.tags.includes(t));
          if (newTags.length > 0) {
            updatedTask.tags = [...updatedTask.tags, ...newTags];
            changes.push('tags');
          }
        }

        if (options.dependsOn) {
          // Validate all dependency refs
          for (const depRef of options.dependsOn) {
            const depResult = index.resolve(depRef);
            if (!depResult.ok) {
              error(`Dependency reference not found: ${depRef}`);
              process.exit(3);
            }
          }
          updatedTask.depends_on = options.dependsOn;
          changes.push('depends_on');
        }

        if (changes.length === 0) {
          warn('No changes specified');
          return;
        }

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-set', foundTask.slugs[0] || index.shortUlid(foundTask._ulid), changes.join(', '));
        success(`Updated task: ${index.shortUlid(updatedTask._ulid)} (${changes.join(', ')})`, { task: updatedTask });
      } catch (err) {
        error('Failed to update task', err);
        process.exit(1);
      }
    });

  // kspec task start <ref>
  task
    .command('start <ref>')
    .description('Start working on a task (pending -> in_progress)')
    .option('--no-sync', 'Skip syncing spec implementation status')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        if (foundTask.status === 'in_progress') {
          warn('Task is already in progress');
          output(foundTask, () => formatTaskDetails(foundTask));
          return;
        }

        if (foundTask.status !== 'pending') {
          error(`Cannot start task with status: ${foundTask.status}`);
          process.exit(4); // Exit code 4 = invalid state
        }

        // Update status
        const updatedTask: Task = {
          ...foundTask,
          status: 'in_progress',
          started_at: new Date().toISOString(),
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-start', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Started task: ${index.shortUlid(updatedTask._ulid)}`, { task: updatedTask });

        // Sync spec implementation status (unless --no-sync)
        if (options.sync !== false && foundTask.spec_ref) {
          const updatedTasks = tasks.map(t =>
            t._ulid === updatedTask._ulid ? { ...t, ...updatedTask } : t
          );
          const syncResult = await syncSpecImplementationStatus(
            ctx,
            updatedTask as LoadedTask,
            updatedTasks as LoadedTask[],
            items,
            index
          );
          if (syncResult) {
            info(`Synced spec "${syncResult.specTitle}" implementation: ${syncResult.previousStatus} -> ${syncResult.newStatus}`);
          }
        }
      } catch (err) {
        error('Failed to start task', err);
        process.exit(1);
      }
    });

  // kspec task complete <ref>
  task
    .command('complete <ref>')
    .description('Complete a task (in_progress -> completed)')
    .option('--reason <reason>', 'Completion reason/notes')
    .option('--no-sync', 'Skip syncing spec implementation status')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        if (foundTask.status === 'completed') {
          warn('Task is already completed');
          output(foundTask, () => formatTaskDetails(foundTask));
          return;
        }

        if (foundTask.status !== 'in_progress' && foundTask.status !== 'pending') {
          error(`Cannot complete task with status: ${foundTask.status}`);
          process.exit(4);
        }

        const now = new Date().toISOString();

        // Update status
        const updatedTask: Task = {
          ...foundTask,
          status: 'completed',
          completed_at: now,
          closed_reason: options.reason || null,
          started_at: foundTask.started_at || now, // Set started_at if not already
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-complete', foundTask.slugs[0] || index.shortUlid(foundTask._ulid), options.reason);
        success(`Completed task: ${index.shortUlid(updatedTask._ulid)}`, { task: updatedTask });

        // Output commit guidance (suppressed in JSON mode)
        if (!isJsonMode()) {
          const guidance = formatCommitGuidance(updatedTask);
          printCommitGuidance(guidance);
        }

        // Sync spec implementation status (unless --no-sync)
        if (options.sync !== false && foundTask.spec_ref) {
          // Update task list to reflect the change we just made
          const updatedTasks = tasks.map(t =>
            t._ulid === updatedTask._ulid ? { ...t, ...updatedTask } : t
          );
          const syncResult = await syncSpecImplementationStatus(
            ctx,
            updatedTask as LoadedTask,
            updatedTasks as LoadedTask[],
            items,
            index
          );
          if (syncResult) {
            info(`Synced spec "${syncResult.specTitle}" implementation: ${syncResult.previousStatus} -> ${syncResult.newStatus}`);
          }
        }
      } catch (err) {
        error('Failed to complete task', err);
        process.exit(1);
      }
    });

  // kspec task block <ref>
  task
    .command('block <ref>')
    .description('Block a task')
    .requiredOption('--reason <reason>', 'Reason for blocking')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        if (foundTask.status === 'completed' || foundTask.status === 'cancelled') {
          error(`Cannot block task with status: ${foundTask.status}`);
          process.exit(4);
        }

        const updatedTask: Task = {
          ...foundTask,
          status: 'blocked',
          blocked_by: [...foundTask.blocked_by, options.reason],
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-block', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Blocked task: ${index.shortUlid(updatedTask._ulid)}`, { task: updatedTask });
      } catch (err) {
        error('Failed to block task', err);
        process.exit(1);
      }
    });

  // kspec task unblock <ref>
  task
    .command('unblock <ref>')
    .description('Unblock a task')
    .action(async (ref: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        if (foundTask.status !== 'blocked') {
          warn('Task is not blocked');
          return;
        }

        const updatedTask: Task = {
          ...foundTask,
          status: 'pending',
          blocked_by: [],
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-unblock', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Unblocked task: ${index.shortUlid(updatedTask._ulid)}`, { task: updatedTask });
      } catch (err) {
        error('Failed to unblock task', err);
        process.exit(1);
      }
    });

  // kspec task cancel <ref>
  task
    .command('cancel <ref>')
    .description('Cancel a task')
    .option('--reason <reason>', 'Cancellation reason')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        if (foundTask.status === 'completed' || foundTask.status === 'cancelled') {
          warn(`Task is already ${foundTask.status}`);
          return;
        }

        const updatedTask: Task = {
          ...foundTask,
          status: 'cancelled',
          closed_reason: options.reason || null,
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-cancel', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Cancelled task: ${index.shortUlid(updatedTask._ulid)}`, { task: updatedTask });
      } catch (err) {
        error('Failed to cancel task', err);
        process.exit(1);
      }
    });

  // kspec task delete <ref>
  task
    .command('delete <ref>')
    .description('Delete a task permanently')
    .option('--force', 'Skip confirmation')
    .option('--dry-run', 'Show what would be deleted without deleting')
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        const taskDisplay = `${foundTask.title} (${index.shortUlid(foundTask._ulid)})`;

        if (options.dryRun) {
          info(`Would delete task: ${taskDisplay}`);
          console.log(`  Source file: ${foundTask._sourceFile}`);
          console.log(`  Status: ${foundTask.status}`);
          if (foundTask.notes.length > 0) {
            console.log(`  Notes: ${foundTask.notes.length}`);
          }
          return;
        }

        // Confirm unless --force
        if (!options.force) {
          const readline = await import('readline');
          const rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout,
          });

          const answer = await new Promise<string>((resolve) => {
            rl.question(`Delete task "${taskDisplay}"? [y/N] `, resolve);
          });
          rl.close();

          if (answer.toLowerCase() !== 'y') {
            info('Deletion cancelled');
            return;
          }
        }

        await deleteTask(ctx, foundTask);
        await commitIfShadow(ctx.shadow, 'task-delete', foundTask.slugs[0] || index.shortUlid(foundTask._ulid), foundTask.title);
        success(`Deleted task: ${taskDisplay}`);
      } catch (err) {
        error('Failed to delete task', err);
        process.exit(1);
      }
    });

  // kspec task note <ref> <message>
  task
    .command('note <ref> <message>')
    .description('Add a note to a task')
    .option('--author <author>', 'Note author')
    .option('--supersedes <ulid>', 'ULID of note this supersedes')
    .action(async (ref: string, message: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        const note = createNote(message, options.author, options.supersedes);

        const updatedTask: Task = {
          ...foundTask,
          notes: [...foundTask.notes, note],
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-note', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Added note to task: ${index.shortUlid(updatedTask._ulid)}`, { note });

        // Proactive alignment guidance for tasks with spec_ref
        if (foundTask.spec_ref) {
          console.log('');
          console.log('\x1b[33m--- Alignment Check ---\x1b[0m');
          console.log('Did your implementation add anything beyond the original spec?');
          console.log('If so, consider updating the spec:');
          console.log(`  kspec item set ${foundTask.spec_ref} --description "Updated description"`);
          console.log('Or add acceptance criteria for new features.');

          // Check if linked spec has acceptance criteria and remind about test coverage
          const specResult = index.resolve(foundTask.spec_ref);
          if (specResult.ok && specResult.item) {
            const specItem = specResult.item as { acceptance_criteria?: unknown[] };
            if (specItem.acceptance_criteria && specItem.acceptance_criteria.length > 0) {
              console.log('');
              console.log(`Linked spec has ${specItem.acceptance_criteria.length} acceptance criteria - consider test coverage.`);
            }
          }
        }
      } catch (err) {
        error('Failed to add note', err);
        process.exit(1);
      }
    });

  // kspec task notes <ref>
  task
    .command('notes <ref>')
    .description('Show notes for a task')
    .action(async (ref: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        output(foundTask.notes, () => {
          if (foundTask.notes.length === 0) {
            console.log('No notes');
          } else {
            for (const note of foundTask.notes) {
              const author = note.author || 'unknown';
              console.log(`[${note.created_at}] ${author}:`);
              console.log(note.content);
              console.log('');
            }
          }
        });
      } catch (err) {
        error('Failed to get notes', err);
        process.exit(1);
      }
    });

  // kspec task todos <ref>
  task
    .command('todos <ref>')
    .description('Show todos for a task')
    .action(async (ref: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        output(foundTask.todos, () => {
          if (foundTask.todos.length === 0) {
            console.log('No todos');
          } else {
            for (const todo of foundTask.todos) {
              const status = todo.done ? '[x]' : '[ ]';
              const doneInfo = todo.done && todo.done_at ? ` (done ${todo.done_at})` : '';
              console.log(`${status} ${todo.id}. ${todo.text}${doneInfo}`);
            }
          }
        });
      } catch (err) {
        error('Failed to get todos', err);
        process.exit(1);
      }
    });

  // Create subcommand group for todo operations
  const todoCmd = task
    .command('todo')
    .description('Manage task todos');

  // kspec task todo add <ref> <text>
  todoCmd
    .command('add <ref> <text>')
    .description('Add a todo to a task')
    .option('--author <author>', 'Todo author')
    .action(async (ref: string, text: string, options) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        // Calculate next ID (max existing + 1, or 1 if none)
        const nextId = foundTask.todos.length > 0
          ? Math.max(...foundTask.todos.map(t => t.id)) + 1
          : 1;

        const todo = createTodo(nextId, text, options.author);

        const updatedTask: Task = {
          ...foundTask,
          todos: [...foundTask.todos, todo],
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-note', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Added todo #${todo.id} to task: ${index.shortUlid(updatedTask._ulid)}`, { todo });
      } catch (err) {
        error('Failed to add todo', err);
        process.exit(1);
      }
    });

  // kspec task todo done <ref> <id>
  todoCmd
    .command('done <ref> <id>')
    .description('Mark a todo as done')
    .action(async (ref: string, idStr: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        const id = parseInt(idStr, 10);
        if (isNaN(id)) {
          error(`Invalid todo ID: ${idStr}`);
          process.exit(3);
        }

        const todoIndex = foundTask.todos.findIndex(t => t.id === id);
        if (todoIndex === -1) {
          error(`Todo #${id} not found`);
          process.exit(3);
        }

        if (foundTask.todos[todoIndex].done) {
          warn(`Todo #${id} is already done`);
          return;
        }

        const updatedTodos = [...foundTask.todos];
        updatedTodos[todoIndex] = {
          ...updatedTodos[todoIndex],
          done: true,
          done_at: new Date().toISOString(),
        };

        const updatedTask: Task = {
          ...foundTask,
          todos: updatedTodos,
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-note', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Marked todo #${id} as done`, { todo: updatedTodos[todoIndex] });
      } catch (err) {
        error('Failed to mark todo as done', err);
        process.exit(1);
      }
    });

  // kspec task todo undone <ref> <id>
  todoCmd
    .command('undone <ref> <id>')
    .description('Mark a todo as not done')
    .action(async (ref: string, idStr: string) => {
      try {
        const ctx = await initContext();
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        const id = parseInt(idStr, 10);
        if (isNaN(id)) {
          error(`Invalid todo ID: ${idStr}`);
          process.exit(3);
        }

        const todoIndex = foundTask.todos.findIndex(t => t.id === id);
        if (todoIndex === -1) {
          error(`Todo #${id} not found`);
          process.exit(3);
        }

        if (!foundTask.todos[todoIndex].done) {
          warn(`Todo #${id} is not done`);
          return;
        }

        const updatedTodos = [...foundTask.todos];
        updatedTodos[todoIndex] = {
          ...updatedTodos[todoIndex],
          done: false,
          done_at: undefined,
        };

        const updatedTask: Task = {
          ...foundTask,
          todos: updatedTodos,
        };

        await saveTask(ctx, updatedTask);
        await commitIfShadow(ctx.shadow, 'task-note', foundTask.slugs[0] || index.shortUlid(foundTask._ulid));
        success(`Marked todo #${id} as not done`, { todo: updatedTodos[todoIndex] });
      } catch (err) {
        error('Failed to mark todo as not done', err);
        process.exit(1);
      }
    });
}

/**
 * Meta manifest loading and operations.
 *
 * The meta manifest (kynetic.meta.yaml) contains process definitions:
 * - Agents: roles, capabilities, conventions
 * - Workflows: structured processes with steps
 * - Conventions: project rules and standards
 * - Observations: feedback about processes
 */

import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { ulid } from 'ulid';
import {
  MetaManifestSchema,
  AgentSchema,
  WorkflowSchema,
  ConventionSchema,
  ObservationSchema,
  type MetaManifest,
  type Agent,
  type Workflow,
  type Convention,
  type Observation,
  type MetaItem,
  type ObservationType,
  getMetaItemType,
} from '../schema/index.js';
import { readYamlFile, writeYamlFile, expandIncludePattern, getAuthor } from './yaml.js';
import type { KspecContext } from './yaml.js';

/**
 * Loaded agent with runtime metadata
 */
export interface LoadedAgent extends Agent {
  _sourceFile?: string;
}

/**
 * Loaded workflow with runtime metadata
 */
export interface LoadedWorkflow extends Workflow {
  _sourceFile?: string;
}

/**
 * Loaded convention with runtime metadata
 */
export interface LoadedConvention extends Convention {
  _sourceFile?: string;
}

/**
 * Loaded observation with runtime metadata
 */
export interface LoadedObservation extends Observation {
  _sourceFile?: string;
}

/**
 * Any loaded meta item
 */
export type LoadedMetaItem = LoadedAgent | LoadedWorkflow | LoadedConvention | LoadedObservation;

/**
 * Meta context containing all loaded meta items
 */
export interface MetaContext {
  manifest: MetaManifest | null;
  manifestPath: string | null;
  agents: LoadedAgent[];
  workflows: LoadedWorkflow[];
  conventions: LoadedConvention[];
  observations: LoadedObservation[];
}

/**
 * Find the meta manifest file (kynetic.meta.yaml)
 */
export async function findMetaManifest(specDir: string): Promise<string | null> {
  const candidates = ['kynetic.meta.yaml'];

  for (const candidate of candidates) {
    const filePath = path.join(specDir, candidate);
    try {
      await fs.access(filePath);
      return filePath;
    } catch {
      // File doesn't exist, try next
    }
  }

  return null;
}

/**
 * Get the meta manifest file path.
 * Returns path even if file doesn't exist yet.
 */
export function getMetaManifestPath(ctx: KspecContext): string {
  return path.join(ctx.specDir, 'kynetic.meta.yaml');
}

/**
 * Load meta items from a single file.
 */
async function loadMetaFile(
  filePath: string
): Promise<{
  agents: LoadedAgent[];
  workflows: LoadedWorkflow[];
  conventions: LoadedConvention[];
  observations: LoadedObservation[];
}> {
  const result: {
    agents: LoadedAgent[];
    workflows: LoadedWorkflow[];
    conventions: LoadedConvention[];
    observations: LoadedObservation[];
  } = {
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
  };

  try {
    const raw = await readYamlFile<unknown>(filePath);
    if (!raw || typeof raw !== 'object') {
      return result;
    }

    const obj = raw as Record<string, unknown>;

    // Parse agents
    if (Array.isArray(obj.agents)) {
      for (const agent of obj.agents) {
        const parsed = AgentSchema.safeParse(agent);
        if (parsed.success) {
          result.agents.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }

    // Parse workflows
    if (Array.isArray(obj.workflows)) {
      for (const workflow of obj.workflows) {
        const parsed = WorkflowSchema.safeParse(workflow);
        if (parsed.success) {
          result.workflows.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }

    // Parse conventions
    if (Array.isArray(obj.conventions)) {
      for (const convention of obj.conventions) {
        const parsed = ConventionSchema.safeParse(convention);
        if (parsed.success) {
          result.conventions.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }

    // Parse observations
    if (Array.isArray(obj.observations)) {
      for (const observation of obj.observations) {
        const parsed = ObservationSchema.safeParse(observation);
        if (parsed.success) {
          result.observations.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }
  } catch {
    // File doesn't exist or parse error
  }

  return result;
}

/**
 * Load the meta context from a kspec context.
 * Loads meta manifest and follows includes.
 */
export async function loadMetaContext(ctx: KspecContext): Promise<MetaContext> {
  const result: MetaContext = {
    manifest: null,
    manifestPath: null,
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
  };

  const manifestPath = await findMetaManifest(ctx.specDir);
  if (!manifestPath) {
    return result;
  }

  result.manifestPath = manifestPath;

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);

    if (!parsed.success) {
      // Invalid manifest, but we can still try to extract items
      const items = await loadMetaFile(manifestPath);
      result.agents.push(...items.agents);
      result.workflows.push(...items.workflows);
      result.conventions.push(...items.conventions);
      result.observations.push(...items.observations);
      return result;
    }

    result.manifest = parsed.data;

    // Load items from manifest
    const manifestItems = await loadMetaFile(manifestPath);
    result.agents.push(...manifestItems.agents);
    result.workflows.push(...manifestItems.workflows);
    result.conventions.push(...manifestItems.conventions);
    result.observations.push(...manifestItems.observations);

    // Process includes
    const includes = parsed.data.includes || [];
    const manifestDir = path.dirname(manifestPath);

    for (const include of includes) {
      const expandedPaths = await expandIncludePattern(include, manifestDir);

      for (const filePath of expandedPaths) {
        const items = await loadMetaFile(filePath);
        result.agents.push(...items.agents);
        result.workflows.push(...items.workflows);
        result.conventions.push(...items.conventions);
        result.observations.push(...items.observations);
      }
    }
  } catch {
    // Manifest exists but may be invalid
  }

  return result;
}

/**
 * Get meta stats summary
 */
export function getMetaStats(meta: MetaContext): {
  agents: number;
  workflows: number;
  conventions: number;
  observations: number;
  unresolvedObservations: number;
} {
  return {
    agents: meta.agents.length,
    workflows: meta.workflows.length,
    conventions: meta.conventions.length,
    observations: meta.observations.length,
    unresolvedObservations: meta.observations.filter((o) => !o.resolved).length,
  };
}

/**
 * Find a meta item by reference (ULID, short ULID, or id)
 */
export function findMetaItemByRef(
  meta: MetaContext,
  ref: string
): LoadedMetaItem | undefined {
  const cleanRef = ref.startsWith('@') ? ref.slice(1) : ref;

  // Search all item types
  const allItems: LoadedMetaItem[] = [
    ...meta.agents,
    ...meta.workflows,
    ...meta.conventions,
    ...meta.observations,
  ];

  for (const item of allItems) {
    // Match full ULID
    if (item._ulid === cleanRef) return item;

    // Match short ULID (prefix)
    if (item._ulid.toLowerCase().startsWith(cleanRef.toLowerCase())) return item;

    // Match by id (for agents and workflows)
    if ('id' in item && item.id === cleanRef) return item;

    // Match by domain (for conventions)
    if ('domain' in item && item.domain === cleanRef) return item;
  }

  return undefined;
}

/**
 * Determine if an item is a meta item type
 */
export function isMetaItemType(type: string): boolean {
  return ['agent', 'workflow', 'convention', 'observation'].includes(type);
}

// ============================================================
// META ITEM CRUD
// ============================================================

/**
 * Save the entire meta manifest to file
 */
async function saveMetaManifest(
  manifestPath: string,
  manifest: MetaManifest
): Promise<void> {
  await writeYamlFile(manifestPath, manifest);
}

/**
 * Strip runtime metadata before serialization
 */
function stripMetaMetadata<T extends LoadedMetaItem>(item: T): Omit<T, '_sourceFile'> {
  const { _sourceFile, ...cleanItem } = item;
  return cleanItem as Omit<T, '_sourceFile'>;
}

/**
 * Create a new observation
 */
export function createObservation(
  type: ObservationType,
  content: string,
  options: {
    workflow_ref?: string;
    author?: string;
  } = {}
): Observation {
  return {
    _ulid: ulid(),
    type,
    content,
    workflow_ref: options.workflow_ref,
    created_at: new Date().toISOString(),
    author: options.author ?? getAuthor(),
    resolved: false,
    resolution: null,
  };
}

/**
 * Save an observation to the meta manifest
 */
export async function saveObservation(
  ctx: KspecContext,
  observation: LoadedObservation
): Promise<void> {
  const manifestPath = getMetaManifestPath(ctx);

  // Ensure directory exists
  const dir = path.dirname(manifestPath);
  await fs.mkdir(dir, { recursive: true });

  // Load existing manifest
  let manifest: MetaManifest = {
    kynetic_meta: '1.0',
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
    includes: [],
  };

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (parsed.success) {
      manifest = parsed.data;
    }
  } catch {
    // File doesn't exist, use defaults
  }

  // Strip runtime metadata
  const cleanObs = stripMetaMetadata(observation);

  // Update or add
  const existingIndex = manifest.observations.findIndex(
    (o) => o._ulid === observation._ulid
  );
  if (existingIndex >= 0) {
    manifest.observations[existingIndex] = cleanObs as Observation;
  } else {
    manifest.observations.push(cleanObs as Observation);
  }

  await saveMetaManifest(manifestPath, manifest);
}

/**
 * Delete an observation from the meta manifest
 */
export async function deleteObservation(
  ctx: KspecContext,
  ulid: string
): Promise<boolean> {
  const manifestPath = getMetaManifestPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (!parsed.success) {
      return false;
    }

    const manifest = parsed.data;
    const index = manifest.observations.findIndex((o) => o._ulid === ulid);
    if (index < 0) {
      return false;
    }

    manifest.observations.splice(index, 1);
    await saveMetaManifest(manifestPath, manifest);
    return true;
  } catch {
    return false;
  }
}

// Re-export the getMetaItemType function
export { getMetaItemType };
export type { Agent, Workflow, Convention, Observation, MetaItem };

// ============================================================
// GENERIC META ITEM CRUD
// ============================================================

/**
 * Save any meta item (agent, workflow, convention) to the manifest
 */
export async function saveMetaItem(
  ctx: KspecContext,
  item: LoadedMetaItem,
  itemType: 'agent' | 'workflow' | 'convention'
): Promise<void> {
  const manifestPath = getMetaManifestPath(ctx);

  // Ensure directory exists
  const dir = path.dirname(manifestPath);
  await fs.mkdir(dir, { recursive: true });

  // Load existing manifest
  let manifest: MetaManifest = {
    kynetic_meta: '1.0',
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
    includes: [],
  };

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (parsed.success) {
      manifest = parsed.data;
    }
  } catch {
    // File doesn't exist, use defaults
  }

  // Strip runtime metadata
  const cleanItem = stripMetaMetadata(item);

  // Get the appropriate array
  const getArray = () => {
    switch (itemType) {
      case 'agent':
        return manifest.agents;
      case 'workflow':
        return manifest.workflows;
      case 'convention':
        return manifest.conventions;
    }
  };

  const array = getArray();

  // Update or add
  const existingIndex = array.findIndex((i) => i._ulid === item._ulid);
  if (existingIndex >= 0) {
    (array as unknown[])[existingIndex] = cleanItem;
  } else {
    (array as unknown[]).push(cleanItem);
  }

  await saveMetaManifest(manifestPath, manifest);
}

/**
 * Delete any meta item from the manifest
 */
export async function deleteMetaItem(
  ctx: KspecContext,
  itemUlid: string,
  itemType: 'agent' | 'workflow' | 'convention' | 'observation'
): Promise<boolean> {
  const manifestPath = getMetaManifestPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (!parsed.success) {
      return false;
    }

    const manifest = parsed.data;

    const getArray = () => {
      switch (itemType) {
        case 'agent':
          return manifest.agents;
        case 'workflow':
          return manifest.workflows;
        case 'convention':
          return manifest.conventions;
        case 'observation':
          return manifest.observations;
      }
    };

    const array = getArray();
    const index = array.findIndex((i) => i._ulid === itemUlid);
    if (index < 0) {
      return false;
    }

    array.splice(index, 1);
    await saveMetaManifest(manifestPath, manifest);
    return true;
  } catch {
    return false;
  }
}

// ============================================================
// SESSION CONTEXT
// ============================================================

/**
 * Session context for ephemeral session state
 */
export interface SessionContext {
  focus: string | null;
  threads: string[];
  open_questions: string[];
  updated_at: string;
}

/**
 * Get the session context file path
 */
export function getSessionContextPath(ctx: KspecContext): string {
  return path.join(ctx.specDir, '.kspec-session');
}

/**
 * Load session context (or return empty context if not exists)
 */
export async function loadSessionContext(ctx: KspecContext): Promise<SessionContext> {
  const contextPath = getSessionContextPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(contextPath);
    if (!raw || typeof raw !== 'object') {
      return {
        focus: null,
        threads: [],
        open_questions: [],
        updated_at: new Date().toISOString(),
      };
    }

    const obj = raw as Record<string, unknown>;
    return {
      focus: typeof obj.focus === 'string' ? obj.focus : null,
      threads: Array.isArray(obj.threads) ? obj.threads.filter((t): t is string => typeof t === 'string') : [],
      open_questions: Array.isArray(obj.open_questions) ? obj.open_questions.filter((q): q is string => typeof q === 'string') : [],
      updated_at: typeof obj.updated_at === 'string' ? obj.updated_at : new Date().toISOString(),
    };
  } catch {
    return {
      focus: null,
      threads: [],
      open_questions: [],
      updated_at: new Date().toISOString(),
    };
  }
}

/**
 * Save session context
 */
export async function saveSessionContext(ctx: KspecContext, context: SessionContext): Promise<void> {
  const contextPath = getSessionContextPath(ctx);

  // Update timestamp
  context.updated_at = new Date().toISOString();

  await writeYamlFile(contextPath, context);
}

/**
 * Reference resolution system for @references.
 *
 * Handles resolution of @slug and @ulid references to actual items,
 * with proper error handling for not-found and ambiguous cases.
 */

import type { LoadedSpecItem, LoadedTask, AnyLoadedItem } from './yaml.js';
import type { LoadedMetaItem } from './meta.js';

// ============================================================
// TYPES
// ============================================================

/**
 * Successful resolution result
 * AC: @agent-definitions ac-agent-3
 */
export interface ResolveSuccess {
  ok: true;
  ulid: string;
  item: AnyLoadedItem | LoadedMetaItem;
  /** How the reference was matched */
  matchType: 'slug' | 'ulid-full' | 'ulid-prefix';
}

/**
 * Failed resolution - reference not found
 */
export interface ResolveNotFound {
  ok: false;
  error: 'not_found';
  ref: string;
}

/**
 * Failed resolution - ambiguous ULID prefix
 */
export interface ResolveAmbiguous {
  ok: false;
  error: 'ambiguous';
  ref: string;
  /** The matching ULIDs */
  candidates: string[];
}

/**
 * Failed resolution - duplicate slug
 */
export interface ResolveDuplicateSlug {
  ok: false;
  error: 'duplicate_slug';
  ref: string;
  /** The ULIDs that share this slug */
  candidates: string[];
}

export type ResolveResult =
  | ResolveSuccess
  | ResolveNotFound
  | ResolveAmbiguous
  | ResolveDuplicateSlug;

/**
 * Validation error for a single reference
 */
export interface RefValidationError {
  /** The reference string that failed */
  ref: string;
  /** Where this reference was found */
  sourceFile?: string;
  /** The item containing this reference */
  sourceUlid?: string;
  /** The field containing this reference */
  field: string;
  /** Error type */
  error: 'not_found' | 'ambiguous' | 'duplicate_slug';
  /** Additional context */
  message: string;
}

// ============================================================
// REFERENCE INDEX
// ============================================================

/**
 * Index for efficient reference resolution.
 * Build once when loading the spec, then resolve many times.
 * AC: @agent-definitions ac-agent-3
 */
export class ReferenceIndex {
  /** slug → ULID mapping */
  private slugIndex = new Map<string, string[]>();

  /** ULID → item mapping */
  private ulidIndex = new Map<string, AnyLoadedItem | LoadedMetaItem>();

  /** All ULIDs for prefix matching */
  private allUlids: string[] = [];

  /**
   * Build index from loaded items and meta items
   * AC: @agent-definitions ac-agent-3
   */
  constructor(
    tasks: LoadedTask[],
    items: LoadedSpecItem[],
    metaItems: LoadedMetaItem[] = []
  ) {
    // Index tasks
    for (const task of tasks) {
      this.indexItem(task);
    }

    // Index spec items
    for (const item of items) {
      this.indexItem(item);
    }

    // Index meta items (agents, workflows, conventions, observations)
    // AC: @agent-definitions ac-agent-3
    for (const metaItem of metaItems) {
      this.indexMetaItem(metaItem);
    }

    // Sort ULIDs for consistent ordering
    this.allUlids.sort();
  }

  private indexItem(item: AnyLoadedItem): void {
    const ulid = item._ulid;

    // Index by ULID
    this.ulidIndex.set(ulid, item);
    this.allUlids.push(ulid);

    // Index by slugs
    for (const slug of item.slugs) {
      const existing = this.slugIndex.get(slug);
      if (existing) {
        existing.push(ulid);
      } else {
        this.slugIndex.set(slug, [ulid]);
      }
    }
  }

  /**
   * Index a meta item (agent, workflow, convention, observation)
   * Meta items use 'id' field as their slug
   * AC: @agent-definitions ac-agent-3
   */
  private indexMetaItem(item: LoadedMetaItem): void {
    const ulid = item._ulid;

    // Index by ULID
    this.ulidIndex.set(ulid, item);
    this.allUlids.push(ulid);

    // Index by id (acts like a slug for meta items)
    const metaItem = item as { id?: string };
    if (metaItem.id) {
      const existing = this.slugIndex.get(metaItem.id);
      if (existing) {
        existing.push(ulid);
      } else {
        this.slugIndex.set(metaItem.id, [ulid]);
      }
    }
  }

  /**
   * Resolve a reference to an item.
   *
   * Resolution order:
   * 1. Exact slug match
   * 2. Full ULID match
   * 3. ULID prefix match (must be unique)
   */
  resolve(ref: string): ResolveResult {
    // Strip @ prefix if present
    const cleanRef = ref.startsWith('@') ? ref.slice(1) : ref;
    const cleanRefLower = cleanRef.toLowerCase();

    // 1. Try slug match first
    const slugMatches = this.slugIndex.get(cleanRef);
    if (slugMatches) {
      if (slugMatches.length > 1) {
        return {
          ok: false,
          error: 'duplicate_slug',
          ref,
          candidates: slugMatches,
        };
      }
      const ulid = slugMatches[0];
      const item = this.ulidIndex.get(ulid)!;
      return { ok: true, ulid, item, matchType: 'slug' };
    }

    // 2. Try full ULID match
    const exactMatch = this.ulidIndex.get(cleanRef.toUpperCase());
    if (exactMatch) {
      return {
        ok: true,
        ulid: exactMatch._ulid,
        item: exactMatch,
        matchType: 'ulid-full',
      };
    }

    // 3. Try ULID prefix match
    const prefixMatches = this.allUlids.filter(ulid =>
      ulid.toLowerCase().startsWith(cleanRefLower)
    );

    if (prefixMatches.length === 0) {
      return { ok: false, error: 'not_found', ref };
    }

    if (prefixMatches.length > 1) {
      return {
        ok: false,
        error: 'ambiguous',
        ref,
        candidates: prefixMatches,
      };
    }

    const ulid = prefixMatches[0];
    const item = this.ulidIndex.get(ulid)!;
    return { ok: true, ulid, item, matchType: 'ulid-prefix' };
  }

  /**
   * Get an item by exact ULID (no resolution, direct lookup)
   */
  getByUlid(ulid: string): AnyLoadedItem | LoadedMetaItem | undefined {
    return this.ulidIndex.get(ulid);
  }

  /**
   * Get the minimum unique prefix for a ULID.
   * Returns the shortest prefix that uniquely identifies this ULID
   * among all indexed items.
   *
   * @param ulid The full ULID to shorten
   * @param minLength Minimum prefix length (default 8)
   * @returns Shortest unique prefix
   */
  shortUlid(ulid: string, minLength = 8): string {
    // Start with minimum length
    let length = minLength;

    while (length < ulid.length) {
      const prefix = ulid.slice(0, length);
      const matches = this.allUlids.filter(u =>
        u.toUpperCase().startsWith(prefix.toUpperCase())
      );

      if (matches.length === 1) {
        return prefix;
      }

      length++;
    }

    // Return full ULID if no shorter unique prefix found
    return ulid;
  }

  /**
   * Get all indexed ULIDs
   */
  getAllUlids(): string[] {
    return [...this.allUlids];
  }

  /**
   * Get all slugs and their mappings
   */
  getAllSlugs(): Map<string, string[]> {
    return new Map(this.slugIndex);
  }

  /**
   * Check if a slug exists
   */
  hasSlug(slug: string): boolean {
    return this.slugIndex.has(slug);
  }

  /**
   * Get count of indexed items
   */
  get size(): number {
    return this.ulidIndex.size;
  }
}

